def compute(vars):
    goodwill = vars["v1"]
    purchase_price = vars["v2"]
    if purchase_price == 0:
        return None

    value = (goodwill / purchase_price) * 100
    return {
        "value": value,
        "trace": {
            "goodwill": goodwill,
            "estimated_purchase_price": purchase_price,
            "percentage": value,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
